INSERT INTO inventory_transactions (business_id, location_id, product_id, transaction_type, quantity_change, quantity_after, reference_type, notes) SELECT @mdl_business_id, l.id, p.id, 'OPENING_BALANCE', 0, 0, 'ACTUAL_STOCK_IMPORT', 'Merged stock import; source item code MA01; ZERO_STOCK|MISSING_COST_PRICE|MISSING_SELLING_PRICE' FROM locations l JOIN products p ON p.business_id = @mdl_business_id AND p.sku = 'MA01' WHERE l.business_id = @mdl_business_id AND l.code = 'LOC-SHOP-A';
INSERT INTO inventory_balances (business_id, location_id, product_id, quantity_on_hand, quantity_reserved, last_transaction_id) SELECT @mdl_business_id, l.id, p.id, 0, 0, t.id FROM locations l JOIN products p ON p.business_id = @mdl_business_id AND p.sku = 'MA01' JOIN inventory_transactions t ON t.business_id = @mdl_business_id AND t.location_id = l.id AND t.product_id = p.id AND t.reference_type = 'ACTUAL_STOCK_IMPORT' WHERE l.business_id = @mdl_business_id AND l.code = 'LOC-SHOP-A';
